'use client'
import { useEffect, useState } from 'react'

export default function InstallPrompt() {
  const [prompt, setPrompt] = useState<any>(null)

  useEffect(() => {
    const handler = (e: Event) => {
      e.preventDefault()
      setPrompt(e)
    }
    window.addEventListener('beforeinstallprompt', handler)
    return () => window.removeEventListener('beforeinstallprompt', handler)
  }, [])

  if (!prompt) return null

  const handleInstall = () => {
    prompt.prompt()
    prompt.userChoice.then(() => setPrompt(null))
  }

  return (
    <div className="fixed bottom-4 left-4 bg-white shadow-lg p-4 rounded">
      <p className="mb-2">Installez Actoos Jobs pour une meilleure expérience.</p>
      <button onClick={handleInstall} className="bg-blue-600 text-white px-4 py-2 rounded">Installer</button>
    </div>
  )
}
