'use client'
import { useState, useEffect } from 'react'

export default function CookieConsent() {
  const [visible, setVisible] = useState(false)

  useEffect(() => {
    const consent = localStorage.getItem('cookie-consent')
    if (!consent) setVisible(true)
  }, [])

  const accept = () => {
    localStorage.setItem('cookie-consent', 'true')
    setVisible(false)
  }

  if (!visible) return null

  return (
    <div className="fixed bottom-0 left-0 right-0 bg-gray-800 text-white p-4 flex justify-between items-center">
      <p className="text-sm">Nous utilisons des cookies pour améliorer votre expérience. <a href="/confidentialite" className="underline">En savoir plus</a></p>
      <button onClick={accept} className="bg-green-500 px-4 py-2 rounded ml-4">Accepter</button>
    </div>
  )
}
